export interface IntercomWebhookPayload {
  type: string;
  data: {
    item: {
      id: string;
      state: string;
      conversation_message?: {
        type: string;
        id: string;
        author: {
          type: string;
          id: string;
        };
        body: string;
        created_at: number;
      };
    };
  };
}

export interface IntercomMessage {
  type: string;
  id: string;
  author: {
    type: string;
    id: string;
    name?: string;
    email?: string;
    phone?: string;
  };
  body: string;
  created_at: number;
}

export interface IntercomPages {
  type: string;
  next: {
    starting_after: string;
    page: number;
  } | null;
  page: number;
  per_page: number;
  total_pages: number;
}

export interface IntercomMessagesResponse {
  type: string;
  conversation_messages: IntercomMessage[];
  pages: IntercomPages;
}

export interface NotionRichText {
  type: 'text';
  text: {
    content: string;
  };
  annotations: {
    bold: boolean;
    italic: boolean;
    strikethrough: boolean;
    underline: boolean;
    code: boolean;
    color: string;
  };
  plain_text: string;
}

export interface NotionParagraphBlock {
  object: 'block';
  type: 'paragraph';
  paragraph: {
    rich_text: NotionRichText[];
  };
}

export interface NotionChildrenRequest {
  children: NotionParagraphBlock[];
}

export interface NotionBlockResult {
  object: 'block';
  id: string;
  type: 'paragraph';
  paragraph: {
    rich_text: NotionRichText[];
  };
}

export interface NotionChildrenResponse {
  object: 'list';
  results: NotionBlockResult[];
  has_more: boolean;
  next_cursor: string | null;
}

export interface ConnectorConfig {
  intercomAccessToken: string;
  notionApiKey: string;
  notionBlockId: string;
  notionVersion?: string; // default: '2022-06-28'
  maxRetries?: number; // default: 3
  baseRetryDelayMs?: number; // default: 1000
  maxPages?: number; // default: 50
  fetch?: typeof fetch;
}

interface FetchOptions extends RequestInit {
  headers?: Record<string, string>;
}

async function fetchWithRetry(
  fetchFn: typeof fetch,
  url: string,
  options: FetchOptions,
  maxRetries: number,
  baseDelayMs: number
): Promise<Response> {
  let attempt = 0;
  while (true) {
    const response = await fetchFn(url, options);
    if (response.status === 429 || (response.status >= 500 && response.status < 600)) {
      if (attempt >= maxRetries) {
        throw new Error(`Request failed after ${maxRetries} retries: ${response.status} ${response.statusText} for ${url}`);
      }
      const retryAfter = response.headers.get('Retry-After');
      let delayMs: number;
      if (retryAfter) {
        const parsed = parseInt(retryAfter, 10);
        if (!isNaN(parsed)) {
          delayMs = parsed * 1000;
        } else {
          // Try parsing as HTTP-date
          const date = new Date(retryAfter);
          if (!isNaN(date.getTime())) {
            delayMs = date.getTime() - Date.now();
            if (delayMs < 0) delayMs = 0;
          } else {
            delayMs = baseDelayMs * Math.pow(2, attempt);
          }
        }
      } else {
        delayMs = baseDelayMs * Math.pow(2, attempt);
      }
      if (isNaN(delayMs) || delayMs < 0) delayMs = baseDelayMs * Math.pow(2, attempt);
      await new Promise(resolve => setTimeout(resolve, delayMs));
      attempt++;
      continue;
    }
    if (!response.ok) {
      throw new Error(`HTTP ${response.status} ${response.statusText} for ${url}`);
    }
    return response;
  }
}

function redactText(text: string): string {
  // Email regex
  const emailRegex = /\b[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,}\b/g;
  // Phone regex: matches various formats like +1-555-123-4567, 555-123-4567, (555) 123-4567, etc.
  const phoneRegex = /(?:\+?\d{1,3}[-.\s]?)?\(?\d{3}\)?[-.\s]?\d{3}[-.\s]?\d{4}\b/g;
  return text.replace(emailRegex, '[REDACTED]').replace(phoneRegex, '[REDACTED]');
}

function buildNotionBlocks(messages: IntercomMessage[]): NotionParagraphBlock[] {
  return messages.map(msg => ({
    object: 'block',
    type: 'paragraph',
    paragraph: {
      rich_text: [
        {
          type: 'text',
          text: { content: redactText(msg.body) },
          annotations: {
            bold: false,
            italic: false,
            strikethrough: false,
            underline: false,
            code: false,
            color: 'default'
          },
          plain_text: redactText(msg.body)
        }
      ]
    }
  }));
}

export async function handle(
  payload: IntercomWebhookPayload,
  config: ConnectorConfig
): Promise<{ notionResponse: NotionChildrenResponse }> {
  const fetchFn = config.fetch ?? fetch;
  const maxRetries = config.maxRetries ?? 3;
  const baseRetryDelayMs = config.baseRetryDelayMs ?? 1000;
  const maxPages = config.maxPages ?? 50;
  const notionVersion = config.notionVersion ?? '2022-06-28';

  // Validate input
  if (!payload || payload.type !== 'conversation.updated') {
    throw new Error('Invalid payload: expected type "conversation.updated"');
  }
  if (!payload.data?.item?.id) {
    throw new Error('Missing conversation ID in payload');
  }
  if (payload.data.item.state !== 'closed') {
    throw new Error('Conversation state is not closed; ignoring');
  }

  const conversationId = payload.data.item.id;

  // Fetch all messages with pagination
  let allMessages: IntercomMessage[] = [];
  let startingAfter: string | null = null;
  let pageCount = 0;

  while (pageCount < maxPages) {
    pageCount++;
    const url = new URL(`https://api.intercom.io/conversations/${conversationId}/messages`);
    if (startingAfter) {
      url.searchParams.set('starting_after', startingAfter);
    }
    url.searchParams.set('per_page', '150'); // max per_page

    const response = await fetchWithRetry(fetchFn, url.toString(), {
      method: 'GET',
      headers: {
        'Authorization': `Bearer ${config.intercomAccessToken}`,
        'Accept': 'application/json'
      }
    }, maxRetries, baseRetryDelayMs);

    const data = await response.json() as IntercomMessagesResponse;
    if (!data.conversation_messages || !Array.isArray(data.conversation_messages)) {
      throw new Error('Invalid Intercom messages response: missing conversation_messages array');
    }
    allMessages = allMessages.concat(data.conversation_messages);

    if (!data.pages?.next?.starting_after) {
      break;
    }
    startingAfter = data.pages.next.starting_after;
  }

  if (allMessages.length === 0) {
    throw new Error('No messages found for conversation');
  }

  // Build Notion children
  const children = buildNotionBlocks(allMessages);

  // Append to Notion
  const notionUrl = `https://api.notion.com/v1/blocks/${config.notionBlockId}/children`;
  const notionResponse = await fetchWithRetry(fetchFn, notionUrl, {
    method: 'PATCH',
    headers: {
      'Authorization': `Bearer ${config.notionApiKey}`,
      'Notion-Version': notionVersion,
      'Content-Type': 'application/json'
    },
    body: JSON.stringify({ children })
  }, maxRetries, baseRetryDelayMs);

  const notionData = await notionResponse.json() as NotionChildrenResponse;
  return { notionResponse: notionData };
}

import { describe, it, expect, vi } from 'vitest';
import { handle, ConnectorConfig, IntercomWebhookPayload } from './connector';
import { SOURCE_EXAMPLE, contractFetch, fakeFetch, jsonResponse, RecordedCall } from './fixtures';

describe('contract', () => {
  it('handles the documented example payload', async () => {
    const { fetch, calls } = contractFetch();
    const config: ConnectorConfig = {
      intercomAccessToken: 'test_intercom_token',
      notionApiKey: 'test_notion_key',
      notionBlockId: 'test_block_id',
      fetch
    };
    const result = await handle(SOURCE_EXAMPLE as unknown as IntercomWebhookPayload, config);
    expect(calls.length).toBeGreaterThan(0);
    expect(result.notionResponse).toBeDefined();
  });
});

describe('handle', () => {
  it('validates required fields', async () => {
    const { fetch, calls } = fakeFetch(() => jsonResponse({}, 200));
    const config: ConnectorConfig = {
      intercomAccessToken: 'token',
      notionApiKey: 'key',
      notionBlockId: 'block',
      fetch
    };

    // Missing type
    await expect(handle({} as unknown as IntercomWebhookPayload, config)).rejects.toThrow('expected type "conversation.updated"');
    // Wrong type
    await expect(handle({ type: 'other', data: { item: { id: '1', state: 'closed' } } } as unknown as IntercomWebhookPayload, config)).rejects.toThrow('expected type "conversation.updated"');
    // Missing conversation ID
    await expect(handle({ type: 'conversation.updated', data: { item: { state: 'closed' } } } as unknown as IntercomWebhookPayload, config)).rejects.toThrow('Missing conversation ID');
    // State not closed
    await expect(handle({ type: 'conversation.updated', data: { item: { id: '1', state: 'open' } } } as unknown as IntercomWebhookPayload, config)).rejects.toThrow('not closed');
  });

  it('fetches all messages with pagination and redacts emails and phones', async () => {
    const intercomResponses = [
      {
        type: 'conversation_message.list',
        conversation_messages: [
          {
            type: 'conversation_message',
            id: 'msg_1',
            author: { type: 'admin', id: 'admin_1', name: 'Support', email: 'support@example.com' },
            body: 'Hello, how can I help?',
            created_at: 1717020000
          },
          {
            type: 'conversation_message',
            id: 'msg_2',
            author: { type: 'user', id: 'user_1', email: 'user@example.com', phone: '+1-555-987-6543' },
            body: 'I need help with billing. My email is user@example.com and phone is 555-123-4567.',
            created_at: 1717020060
          }
        ],
        pages: {
          type: 'pages',
          next: { starting_after: 'cursor123', page: 2 },
          page: 1,
          per_page: 20,
          total_pages: 2
        }
      },
      {
        type: 'conversation_message.list',
        conversation_messages: [
          {
            type: 'conversation_message',
            id: 'msg_3',
            author: { type: 'admin', id: 'admin_2', name: 'Support2' },
            body: 'Another message with phone 555-000-1111.',
            created_at: 1717020100
          }
        ],
        pages: {
          type: 'pages',
          next: null,
          page: 2,
          per_page: 20,
          total_pages: 2
        }
      }
    ];

    let intercomCallCount = 0;
    const { fetch, calls } = fakeFetch((req) => {
      if (req.url.includes('/conversations/') && req.url.includes('/messages')) {
        const response = intercomResponses[intercomCallCount] || intercomResponses[intercomResponses.length - 1];
        intercomCallCount++;
        return jsonResponse(response);
      }
      if (req.url.includes('/blocks/') && req.url.includes('/children')) {
        return jsonResponse({
          object: 'list',
          results: [
            { object: 'block', id: 'block_1', type: 'paragraph', paragraph: { rich_text: [] } }
          ],
          has_more: false,
          next_cursor: null
        });
      }
      return jsonResponse({ error: 'not found' }, 404);
    });

    const config: ConnectorConfig = {
      intercomAccessToken: 'intercom_token',
      notionApiKey: 'notion_key',
      notionBlockId: 'block_123',
      fetch
    };

    const payload: IntercomWebhookPayload = {
      type: 'conversation.updated',
      data: {
        item: {
          id: 'conv_123',
          state: 'closed',
          conversation_message: {
            type: 'conversation_message',
            id: 'msg_123',
            author: { type: 'admin', id: 'admin_123' },
            body: 'Hi team, please review the attached files. Contact me at john@example.com or +1-555-123-4567.',
            created_at: 1717020000
          }
        }
      }
    };

    const result = await handle(payload, config);

    // Check Intercom calls: should be 2 (two pages)
    const intercomCalls = calls.filter(c => c.url.includes('/conversations/') && c.url.includes('/messages'));
    expect(intercomCalls.length).toBe(2);
    // Check auth header
    expect(intercomCalls[0].headers.get('authorization')).toBe('Bearer intercom_token');
    // Check pagination: second call should have starting_after
    expect(intercomCalls[1].url).toContain('starting_after=cursor123');

    // Check Notion call
    const notionCalls = calls.filter(c => c.url.includes('/blocks/') && c.url.includes('/children'));
    expect(notionCalls.length).toBe(1);
    expect(notionCalls[0].method).toBe('PATCH');
    expect(notionCalls[0].headers.get('authorization')).toBe('Bearer notion_key');
    expect(notionCalls[0].headers.get('notion-version')).toBe('2022-06-28');
    const notionBody = notionCalls[0].json as { children: Array<{ paragraph: { rich_text: Array<{ text: { content: string } }> } }> };
    expect(notionBody.children.length).toBe(3); // three messages total
    // Check redaction
    expect(notionBody.children[0].paragraph.rich_text[0].text.content).toBe('Hello, how can I help?');
    expect(notionBody.children[1].paragraph.rich_text[0].text.content).toBe('I need help with billing. My email is [REDACTED] and phone is [REDACTED].');
    expect(notionBody.children[2].paragraph.rich_text[0].text.content).toBe('Another message with phone [REDACTED].');

    expect(result.notionResponse).toBeDefined();
  });

  it('throws on non-2xx Intercom response', async () => {
    const { fetch, calls } = fakeFetch(() => jsonResponse({ error: 'Unauthorized' }, 401));
    const config: ConnectorConfig = {
      intercomAccessToken: 'bad_token',
      notionApiKey: 'key',
      notionBlockId: 'block',
      fetch
    };
    const payload: IntercomWebhookPayload = {
      type: 'conversation.updated',
      data: { item: { id: 'conv_1', state: 'closed' } }
    };
    await expect(handle(payload, config)).rejects.toThrow('HTTP 401 Unauthorized for https://api.intercom.io/conversations/conv_1/messages');
  });

  it('throws on non-2xx Notion response', async () => {
    const { fetch, calls } = fakeFetch((req) => {
      if (req.url.includes('/conversations/')) {
        return jsonResponse({
          type: 'conversation_message.list',
          conversation_messages: [{ type: 'conversation_message', id: 'msg_1', author: { type: 'admin', id: 'a1' }, body: 'Hello', created_at: 1 }],
          pages: { type: 'pages', next: null, page: 1, per_page: 20, total_pages: 1 }
        });
      }
      return jsonResponse({ error: 'Forbidden' }, 403);
    });
    const config: ConnectorConfig = {
      intercomAccessToken: 'token',
      notionApiKey: 'bad_key',
      notionBlockId: 'block',
      fetch
    };
    const payload: IntercomWebhookPayload = {
      type: 'conversation.updated',
      data: { item: { id: 'conv_1', state: 'closed' } }
    };
    await expect(handle(payload, config)).rejects.toThrow('HTTP 403 Forbidden for https://api.notion.com/v1/blocks/block/children');
  });

  it('retries on 429 and succeeds', async () => {
    let attempt = 0;
    const { fetch, calls } = fakeFetch((req) => {
      if (req.url.includes('/conversations/')) {
        if (attempt === 0) {
          attempt++;
          return jsonResponse({ error: 'Too Many Requests' }, 429);
        }
        return jsonResponse({
          type: 'conversation_message.list',
          conversation_messages: [{ type: 'conversation_message', id: 'msg_1', author: { type: 'admin', id: 'a1' }, body: 'Hello', created_at: 1 }],
          pages: { type: 'pages', next: null, page: 1, per_page: 20, total_pages: 1 }
        });
      }
      return jsonResponse({
        object: 'list',
        results: [{ object: 'block', id: 'block_1', type: 'paragraph', paragraph: { rich_text: [] } }],
        has_more: false,
        next_cursor: null
      });
    });

    const config: ConnectorConfig = {
      intercomAccessToken: 'token',
      notionApiKey: 'key',
      notionBlockId: 'block',
      maxRetries: 3,
      baseRetryDelayMs: 10, // small delay for test
      fetch
    };
    const payload: IntercomWebhookPayload = {
      type: 'conversation.updated',
      data: { item: { id: 'conv_1', state: 'closed' } }
    };
    const result = await handle(payload, config);
    // Should have 2 Intercom calls (initial + 1 retry) and 1 Notion call
    const intercomCalls = calls.filter(c => c.url.includes('/conversations/'));
    expect(intercomCalls.length).toBe(2);
    expect(result.notionResponse).toBeDefined();
  });

  it('retries up to maxRetries then throws', async () => {
    const { fetch, calls } = fakeFetch(() => jsonResponse({ error: 'Too Many Requests' }, 429));
    const config: ConnectorConfig = {
      intercomAccessToken: 'token',
      notionApiKey: 'key',
      notionBlockId: 'block',
      maxRetries: 2,
      baseRetryDelayMs: 10,
      fetch
    };
    const payload: IntercomWebhookPayload = {
      type: 'conversation.updated',
      data: { item: { id: 'conv_1', state: 'closed' } }
    };
    await expect(handle(payload, config)).rejects.toThrow('Request failed after 2 retries');
    // Should have 3 calls (initial + 2 retries)
    const intercomCalls = calls.filter(c => c.url.includes('/conversations/'));
    expect(intercomCalls.length).toBe(3);
  });
});

# Intercom to Notion Transcript Connector

This connector processes an Intercom `conversation.updated` webhook (when a conversation is closed), fetches the full message transcript via the Intercom API (with pagination), redacts email addresses and phone numbers from message bodies, and appends the cleaned messages as rich-text paragraph blocks to a specified Notion block (page or block).

## Configuration

The connector requires the following environment variables (passed via `ConnectorConfig`):

| Config Property | Environment Variable | Description |
|-----------------|----------------------|-------------|
| `intercomAccessToken` | `INTERCOM_ACCESS_TOKEN` | Bearer token for Intercom API authentication. |
| `notionApiKey` | `NOTION_API_KEY` | Bearer token for Notion API authentication. |
| `notionBlockId` | (none, must be provided) | The Notion block ID (page or block) to which children will be appended. |
| `notionVersion` | `NOTION_VERSION` (optional) | Notion API version header. Defaults to `2022-06-28`. |
| `maxRetries` | (optional) | Maximum retry attempts for 429/5xx responses. Default: 3. |
| `baseRetryDelayMs` | (optional) | Base delay in ms for exponential backoff. Default: 1000. |
| `maxPages` | (optional) | Hard cap on pagination pages. Default: 50. |

## Usage Example

```typescript
import { handle } from './connector';

const payload = {
  type: 'conversation.updated',
  data: {
    item: {
      id: 'conv_123',
      state: 'closed',
      conversation_message: { ... }
    }
  }
};

const config = {
  intercomAccessToken: process.env.INTERCOM_ACCESS_TOKEN!,
  notionApiKey: process.env.NOTION_API_KEY!,
  notionBlockId: 'your-notion-block-id',
  notionVersion: '2022-06-28'
};

const result = await handle(payload, config);
console.log('Notion response:', result.notionResponse);
```

## Assumptions

1. The webhook fires only when a conversation state changes to `closed` and includes a conversation ID.
2. Intercom's conversation messages endpoint supports pagination via the `starting_after` cursor parameter; pagination stops when `pages.next` is null.
3. Message bodies are plain text (Intercom API v2.15+). HTML bodies are not handled.
4. Email and phone number patterns follow standard formats; redaction uses regex replacements with `[REDACTED]`.
5. The Notion integration has permission to append children to the specified block.
6. Redaction is applied to the entire message body string before constructing Notion rich-text blocks.
7. The Notion `Notion-Version` header is required; a sensible default is used if not provided.
8. Retry logic follows exponential backoff with `Retry-After` header support (both seconds and HTTP-date).
9. Pagination loops are capped at 50 pages (configurable) to prevent runaway loops.

