interface FetchOptions extends RequestInit {
  headers?: Record<string, string>;
}

async function fetchWithRetry(
  fetchFn: typeof fetch,
  url: string,
  options: FetchOptions,
  maxRetries: number,
  baseDelayMs: number
): Promise<Response> {
  let attempt = 0;
  while (true) {
    const response = await fetchFn(url, options);
    if (response.status === 429 || (response.status >= 500 && response.status < 600)) {
      if (attempt >= maxRetries) {
        throw new Error(`Request failed after ${maxRetries} retries: ${response.status} ${response.statusText} for ${url}`);
      }
      const retryAfter = response.headers.get('Retry-After');
      let delayMs: number;
      if (retryAfter) {
        const parsed = parseInt(retryAfter, 10);
        if (!isNaN(parsed)) {
          delayMs = parsed * 1000;
        } else {
          // Try parsing as HTTP-date
          const date = new Date(retryAfter);
          if (!isNaN(date.getTime())) {
            delayMs = date.getTime() - Date.now();
            if (delayMs < 0) delayMs = 0;
          } else {
            delayMs = baseDelayMs * Math.pow(2, attempt);
          }
        }
      } else {
        delayMs = baseDelayMs * Math.pow(2, attempt);
      }
      if (isNaN(delayMs) || delayMs < 0) delayMs = baseDelayMs * Math.pow(2, attempt);
      await new Promise(resolve => setTimeout(resolve, delayMs));
      attempt++;
      continue;
    }
    if (!response.ok) {
      throw new Error(`HTTP ${response.status} ${response.statusText} for ${url}`);
    }
    return response;
  }
}

function redactText(text: string): string {
  // Email regex
  const emailRegex = /\b[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,}\b/g;
  // Phone regex: matches various formats like +1-555-123-4567, 555-123-4567, (555) 123-4567, etc.
  const phoneRegex = /(?:\+?\d{1,3}[-.\s]?)?\(?\d{3}\)?[-.\s]?\d{3}[-.\s]?\d{4}\b/g;
  return text.replace(emailRegex, '[REDACTED]').replace(phoneRegex, '[REDACTED]');
}

function buildNotionBlocks(messages: IntercomMessage[]): NotionParagraphBlock[] {
  return messages.map(msg => ({
    object: 'block',
    type: 'paragraph',
    paragraph: {
      rich_text: [
        {
          type: 'text',
          text: { content: redactText(msg.body) },
          annotations: {
            bold: false,
            italic: false,
            strikethrough: false,
            underline: false,
            code: false,
            color: 'default'
          },
          plain_text: redactText(msg.body)
        }
      ]
    }
  }));
}

export async function handle(
  payload: IntercomWebhookPayload,
  config: ConnectorConfig
): Promise<{ notionResponse: NotionChildrenResponse }> {
  const fetchFn = config.fetch ?? fetch;
  const maxRetries = config.maxRetries ?? 3;
  const baseRetryDelayMs = config.baseRetryDelayMs ?? 1000;
  const maxPages = config.maxPages ?? 50;
  const notionVersion = config.notionVersion ?? '2022-06-28';

  // Validate input
  if (!payload || payload.type !== 'conversation.updated') {
    throw new Error('Invalid payload: expected type "conversation.updated"');
  }
  if (!payload.data?.item?.id) {
    throw new Error('Missing conversation ID in payload');
  }
  if (payload.data.item.state !== 'closed') {
    throw new Error('Conversation state is not closed; ignoring');
  }

  const conversationId = payload.data.item.id;

  // Fetch all messages with pagination
  let allMessages: IntercomMessage[] = [];
  let startingAfter: string | null = null;
  let pageCount = 0;

  while (pageCount < maxPages) {
    pageCount++;
    const url = new URL(`https://api.intercom.io/conversations/${conversationId}/messages`);
    if (startingAfter) {
      url.searchParams.set('starting_after', startingAfter);
    }
    url.searchParams.set('per_page', '150'); // max per_page

    const response = await fetchWithRetry(fetchFn, url.toString(), {
      method: 'GET',
      headers: {
        'Authorization': `Bearer ${config.intercomAccessToken}`,
        'Accept': 'application/json'
      }
    }, maxRetries, baseRetryDelayMs);

    const data = await response.json() as IntercomMessagesResponse;
    if (!data.conversation_messages || !Array.isArray(data.conversation_messages)) {
      throw new Error('Invalid Intercom messages response: missing conversation_messages array');
    }
    allMessages = allMessages.concat(data.conversation_messages);

    if (!data.pages?.next?.starting_after) {
      break;
    }
    startingAfter = data.pages.next.starting_after;
  }

  if (allMessages.length === 0) {
    throw new Error('No messages found for conversation');
  }

  // Build Notion children
  const children = buildNotionBlocks(allMessages);

  // Append to Notion
  const notionUrl = `https://api.notion.com/v1/blocks/${config.notionBlockId}/children`;
  const notionResponse = await fetchWithRetry(fetchFn, notionUrl, {
    method: 'PATCH',
    headers: {
      'Authorization': `Bearer ${config.notionApiKey}`,
      'Notion-Version': notionVersion,
      'Content-Type': 'application/json'
    },
    body: JSON.stringify({ children })
  }, maxRetries, baseRetryDelayMs);

  const notionData = await notionResponse.json() as NotionChildrenResponse;
  return { notionResponse: notionData };
}

